package com.lge.plugins.metashift.ui;

import com.lge.plugins.metashift.utils.PathUtils;
import hudson.FilePath;
import java.io.File;
import java.io.IOException;
import org.kohsuke.stapler.StaplerRequest2;
import org.kohsuke.stapler.StaplerResponse2;

/**
 * Keeps the report files generated by the meta-shift layer (gcovr coverage, sentinel mutation
 * testing, gtest unit test) with the build and hands them out as a zip, one archive per recipe.
 *
 * <p>The pages are not served for viewing. Their line-by-line coverage and mutation content is
 * what the plugin's own annotated source page already renders, so serving them would duplicate
 * that view — and doing so safely required a hand-tuned Content-Security-Policy, a content-type
 * allowlist, and an opaque-origin sandbox around third-party HTML. Downloading the archive keeps
 * the full-fidelity original available without any of that.</p>
 *
 * @author Sung Gon Kim
 */
public class RawReportArchive {

  /**
   * Directory holding the archived report files, relative to the build's root directory.
   */
  public static final String ARCHIVE_RELATIVE_PATH = "meta-shift-report/html";

  private final File root;

  /**
   * Default constructor.
   *
   * @param buildRootDir the build's root directory ({@code Run.getRootDir()})
   */
  public RawReportArchive(final File buildRootDir) {
    this.root = archiveDir(buildRootDir);
  }

  /**
   * Returns the archive directory for the given build root, without requiring it to exist.
   *
   * @param buildRootDir the build's root directory
   * @return the archive directory
   */
  public static File archiveDir(final File buildRootDir) {
    return new File(buildRootDir, ARCHIVE_RELATIVE_PATH);
  }

  /**
   * Tests whether the given archive-relative path resolves to a directory that can be downloaded.
   *
   * @param relativePath archive-relative path, e.g. {@code "recipe-1.0-r0"}
   * @return true when the directory exists
   */
  public boolean hasDirectory(final String relativePath) {
    File dir = resolve(relativePath);
    return dir != null && dir.isDirectory();
  }

  /**
   * Streams the archived directory at {@link StaplerRequest2#getRestOfPath()} to the response as
   * a zip file. Responds 404 when the path escapes the root or is not a directory.
   *
   * @param req stapler request
   * @param rsp stapler response
   * @throws IOException          if streaming fails
   * @throws InterruptedException if the download is interrupted
   */
  public void serveZip(final StaplerRequest2 req, final StaplerResponse2 rsp)
      throws IOException, InterruptedException {
    File dir = resolve(req.getRestOfPath());
    if (dir == null || !dir.isDirectory()) {
      rsp.sendError(StaplerResponse2.SC_NOT_FOUND, "Raw report not found");
      return;
    }
    rsp.setContentType("application/zip");
    // The name comes from a report directory that already passed NamingUtils, but quote it
    // anyway so a stray quote cannot break out of the header value.
    rsp.setHeader("Content-Disposition",
        "attachment; filename=\"" + dir.getName().replace("\"", "") + ".zip\"");
    new FilePath(dir).zip(rsp.getOutputStream(), "**/*");
  }

  /**
   * Resolves an archive-relative path to a file under {@link #root}, rejecting traversal attempts
   * both by segment inspection ({@link PathUtils#escapesRoot}) and, defensively, by canonical-path
   * containment (this resolves attacker-controlled request paths).
   *
   * @param relativePath archive-relative path from the request or a caller
   * @return the resolved file, or null when the path is invalid
   */
  private File resolve(final String relativePath) {
    if (relativePath == null) {
      return null;
    }
    String trimmed = relativePath.startsWith("/") ? relativePath.substring(1) : relativePath;
    if (trimmed.isEmpty() || PathUtils.escapesRoot(trimmed)) {
      return null;
    }
    try {
      String rootCanonical = root.getCanonicalPath() + File.separator;
      File candidate = new File(root, trimmed);
      if (!candidate.getCanonicalPath().startsWith(rootCanonical)) {
        return null;
      }
      return candidate;
    } catch (IOException ignored) {
      return null;
    }
  }
}
